command:
// Expanded Criticals: roll a critical on one of the damage-type charts.
// Uses the same dialog and roll path as the chat-card critical picker.
// Optional: select a token and target nothing; the default chart is guessed from
// the selected actor's first equipped weapon.
const api = game.modules.get("artantares-advanced-criticals")?.api;
if (!api) return ui.notifications.error(game.i18n.localize("EXPCRIT.Error.NotActive"));
const actor = canvas.tokens?.controlled[0]?.actor ?? game.user.character;
const item = actor?.items.find(i => i.type == "weapon" && i.system.isEquipped) ?? null;
return api.openCriticalDialog({ item });
